const Footer = () => {
        return ( 
                
                        <footer class="d-flex flex-column justify-content-center align-items-center py-3 mt-4 border-top">
                                <ul class="nav col-sm-12 col-md-4 list-unstyled d-flex">
                                        <li class="ms-3"><a class="text-body-secondary" href="#"><i class="bi bi-twitter-x"></i></a></li>
                                        <li class="ms-3"><a class="text-body-secondary" href="#"><i class="bi bi-instagram"></i></a></li>
                                        <li class="ms-3"><a class="text-body-secondary" href="#"><i class="bi bi-facebook"></i></a></li>
                                </ul>
                                <div class="col-md-4 d-flex align-items-center py-3">
                                        <a href="/" class="mb-3 me-2 mb-md-0 text-body-secondary text-decoration-none lh-1">
                                                <i class="bi bi-bootstrap-reboot"></i>
                                        </a>
                                        <span class="mb-3 mb-md-0 text-body-secondary">© 2024 Company, Inc</span>
                                </div>
                        </footer>
             
         );
}
 
export default Footer;
